def fill_rects(grid, odd_color=7, even_color=2):
    """Fill the interior of each hollow single-color rectangle: odd interior area with odd_color, even with even_color."""
    from collections import Counter
    cnt=Counter(v for row in grid for v in row)
    bg=cnt.most_common(1)[0][0]
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    seen=set()
    for i in range(h):
        for j in range(w):
            c=grid[i][j]
            if c==bg or (i,j) in seen or c not in cnt: continue
            cells=[(i,j)]; stack=[(i,j)]; seen.add((i,j))
            while stack:
                y,x=stack.pop()
                for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and grid[ny][nx]==c:
                        seen.add((ny,nx)); cells.append((ny,nx)); stack.append((ny,nx))
            ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
            top,bot,left,right=min(ys),max(ys),min(xs),max(xs)
            # hollow rectangle check: border of bbox all color c, interior all bg
            bh,bw=bot-top+1,right-left+1
            if bh<3 or bw<3: continue
            if any(grid[top+dy][left+dx]!=c for dy in range(bh) for dx in range(bw) if dy in(0,bh-1) or dx in(0,bw-1)): continue
            if any(grid[top+dy][left+dx]!=bg for dy in range(1,bh-1) for dx in range(1,bw-1)): continue
            f=odd_color if (bh-2)*(bw-2)%2 else even_color
            for dy in range(1,bh-1):
                for dx in range(1,bw-1):
                    out[top+dy][left+dx]=f
    return out

